import {captureRoomFurniture} from '../../src/hearthside/roomFurniture.ts';
// Local synthetic authority and source fixtures. Never exported by production Worker assembly.
import {DurableObject} from 'cloudflare:workers';
import {HearthsideGuestRoom,HearthsideGuestCard,HearthsideGuestIndex,handleHearthsideGuests} from '../../workers/hearthsideGuests.ts';
import {guestAuthorityAttestation} from '../../workers/hearthsideGuestAuthority.ts';
import {captureGuestSources,validateGuestSources} from '../../src/hearthside/guestProjection.ts';
import {guestDigest} from '../../src/hearthside/guestContracts.ts';
import {newKittyPiece} from '../../src/core/kittyStudio.ts';
export {HearthsideGuestCard,HearthsideGuestIndex};
export const people={alice:'11111111-1111-4111-a111-111111111111',bob:'22222222-2222-4222-a222-222222222222',cara:'33333333-3333-4333-a333-333333333333',dan:'44444444-4444-4444-a444-444444444444',erin:'55555555-5555-4555-a555-555555555555'};
const rosters={'HH-FIRST':[{memberId:'MEM-A',subject:people.alice},{memberId:'MEM-B',subject:people.bob}],'HH-SECOND':[{memberId:'MEM-C',subject:people.cara},{memberId:'MEM-D',subject:people.dan}]};
export class TestControl extends DurableObject {
 async change(input){await this.ctx.storage.put(input.key,input.value);return {ok:true};}
 async authority(token,input){const expected=await guestAuthorityAttestation(this.env,token,input.p_household_id,input.p_issued_at);if(JSON.stringify(expected)!==JSON.stringify(input)||Math.abs(Date.now()/1000-input.p_issued_at)>31)throw Error('Bad signed proof');const name=token.replace('.synthetic.jwt',''),subject=people[name];if(!subject||await this.ctx.storage.get('revoked-'+name))throw Error('No live session');const hh=input.p_household_id;let principals=hh?(await this.ctx.storage.get('roster-'+hh)||rosters[hh]):[];if(!principals)throw Error('Unknown household');return {version:1,environment:'development',householdId:hh,subject,checkedAt:Date.now(),principals,actorMemberId:principals.find(p=>p.subject===subject)?.memberId??null};}
}
export class TestSource extends DurableObject {
 async change(input){await this.ctx.storage.put(input.key,input.value);return {ok:true};}
 async catalogue(scope){const state=(await this.ctx.storage.get('state'))||{},members=rosters[scope.householdId]?.map(p=>p.memberId)||[];return {furniture:room=>captureRoomFurniture(room,state.furniture||[]),activeMemberIds:members,experience:id=>id==='experience-1'?{revision:state.revision||1,shared:!state.hidden,archived:false,title:state.title||'A day by the water',intention:'Time for each other',balance:99999,bankId:'BANK-SECRET'}:null,note:id=>id==='note-1'?{revision:1,shared:!state.hidden,archived:false,text:'You are welcome here.'}:null,memory:id=>id==='memory-1'?{revision:1,shared:!state.hidden,withdrawn:!!state.withdrawn,title:'An afternoon together',recollections:members.map((memberId,i)=>({memberId,text:i?'I remember the light.':'I remember your laugh.'})),approvals:members.map(memberId=>({memberId,revision:1})),media:state.media?[{id:'source-photo',revision:1,publicationId:state.publicationId||'memory-publication',kind:'image',alt:'A reviewed synthetic pixel'}]:[],publicationId:state.publicationId||'memory-publication',designs:[]}:null,memoryAccess:async binding=>!state.hidden&&!state.withdrawn&&binding.publicationId===(state.publicationId||'memory-publication'),piece:async(designId,pieceId,revision)=>designId==='design-1'&&pieceId==='piece-1'&&revision===1?{revision:1,shared:!state.hidden,archived:false,piece:newKittyPiece('PRIVATE-PIECE-SOURCE','2026-09-12T00:00:00.000Z')}:null,media:async()=>{const bytes=Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jZuoAAAAASUVORK5CYII='),c=>c.charCodeAt(0)).buffer;return {mime:'image/png',sha256:await guestDigest(bytes),bytes};}};}
 async captureGuestSource(scope,input){this.count('capture');return captureGuestSources(input,await this.catalogue(scope));}
 async validateGuestSource(scope,proof,mode){this.count('validate');return validateGuestSources(proof,await this.catalogue(scope),mode);}
 count(key){this.ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS counters(key TEXT PRIMARY KEY,n INTEGER)');this.ctx.storage.sql.exec('INSERT INTO counters VALUES(?,1) ON CONFLICT(key) DO UPDATE SET n=n+1',key);}
 async acceptVaultPublication(scope,ref){this.ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,data TEXT)');const old=this.ctx.storage.sql.exec('SELECT data FROM receipts WHERE id=?',ref.publicationId).toArray()[0];if(old){const receipt=JSON.parse(old.data);if(receipt.digest!==ref.digest)throw Error('Different acceptance');return receipt;}const receipt={...ref,receiptId:'receipt-'+ref.publicationId,acceptedAt:Date.now()};this.ctx.storage.sql.exec('INSERT INTO receipts VALUES(?,?)',ref.publicationId,JSON.stringify(receipt));if(await this.ctx.storage.get('lose-accept')){await this.ctx.storage.put('lose-accept',false);throw Error('Lost accepted acknowledgement');}return receipt;}
 async facts(){this.ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,data TEXT)');return {receipts:this.ctx.storage.sql.exec('SELECT data FROM receipts').toArray().map(r=>JSON.parse(r.data)),state:await this.ctx.storage.get('state')||{},financialSnapshotReads:0};}
}
export class TestRoom extends HearthsideGuestRoom {
 constructor(ctx,env){const fault={mode:''};super(ctx,{...env,HEARTHSIDE_GUEST_ARCHIVE:{get:key=>env.HEARTHSIDE_GUEST_ARCHIVE.get(key),put:async(key,value,options)=>{if(key.endsWith('head.json')&&fault.mode==='before-head'){fault.mode='';throw Error('Synthetic archive outage');}const result=await env.HEARTHSIDE_GUEST_ARCHIVE.put(key,value,options);if(key.endsWith('head.json')&&fault.mode==='after-head'){fault.mode='';throw Error('Synthetic lost acknowledgement');}return result;}}});this.fault=fault;}
 async setFault(mode){this.fault.mode=mode;return {ok:true};}
 async presenceCount(){return this.ctx.storage.sql.exec('SELECT count(*) AS n FROM guest_presence').toArray()[0].n;}
}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/__test/')){try{const input=await request.json();let room;if(input.target==='control')room=env.CONTROL.get(env.CONTROL.idFromName('control'));else if(input.target==='source')room=env.LEDGER_ROOMS.get(env.LEDGER_ROOMS.idFromName('development/'+(input.householdId||'HH-FIRST')));else room=(input.target==='restore'?env.RECOVERY_ROOMS:env.HEARTHSIDE_GUEST_ROOMS).get((input.target==='restore'?env.RECOVERY_ROOMS:env.HEARTHSIDE_GUEST_ROOMS).idFromName(input.target==='restore'?'restored-'+input.id:'development/room/'+input.id));if(input.action==='change')return Response.json(await room.change(input.input));if(input.action==='facts')return Response.json(await room.facts());if(input.action==='fault')return Response.json(await room.setFault(input.mode));if(input.action==='presence')return Response.json(await room.presenceCount());if(input.action==='restore')return Response.json(await room.restoreGuestArchive('room/'+input.id,2));if(input.action==='review')return Response.json(await room.hostReview({environment:'development',householdId:'HH-FIRST',memberId:'MEM-A',subject:people.alice,role:'member',aclEpoch:1,expires:Date.now()+60000},input.id));}catch(e){return Response.json({code:e.message},{status:409});}}
 return await handleHearthsideGuests(request,env)||new Response('',{status:404});}};
